pub fn endSendfile(self: *FileResponseStream) void {
        _ = log("endSendfile", .{});
        if (self.state.response_done) {
            return;
        }
        self.state.response_done = true;
        _ = self.detachResp();
        _ = self.resp.endSendFile(self.sendfile.offset, self.resp.shouldCloseConnection());
        _ = self.on_complete(self.ctx, self.resp);
        _ = self.finish();
}

pub fn onAborted(self: *FileResponseStream, _: AnyResponse) void {
        _ = log("onAborted", .{});
        if ((!self.state.response_done)) {
            self.state.response_done = true;
            _ = self.detachResp();
            _ = ((self.on_abort) orelse (self.on_complete))(self.ctx, self.resp);
        }
        _ = self.finish();
}

pub fn failWith(self: *FileResponseStream, err: bun.sys.Error) void {
        if ((!self.state.response_done)) {
            self.state.response_done = true;
            self.state.errored = true;
            _ = self.detachResp();
            _ = self.resp.forceClose();
            _ = self.on_error(self.ctx, self.resp, err);
        }
        _ = self.finish();
}

pub fn detachResp(self: *FileResponseStream) void {
        if (self.state.resp_detached) {
            return;
        }
        self.state.resp_detached = true;
        _ = self.resp.clearOnWritable();
        _ = self.resp.clearAborted();
        _ = self.resp.clearTimeout();
}

pub fn finish(self: *FileResponseStream) void {
        _ = log("finish (already={})", .{ self.state.finished });
        if (self.state.finished) {
            return;
        }
        self.state.finished = true;
        if ((!self.state.response_done)) {
            self.state.response_done = true;
            _ = self.detachResp();
            _ = self.resp.endWithoutBody(self.resp.shouldCloseConnection());
            _ = self.on_complete(self.ctx, self.resp);
        }
        _ = self.deref();
}

pub fn releaseInternal(self: *FileResponseStream) void {
        _ = log("release", .{});
        if ((self.mode == .reader)) {
            _ = self.reader.deinit();
        }
        if (self.auto_close) {
            if (comptime bun.Environment.isWindows) {
                _ = bun.Async.Closer.close(self.fd, bun.windows.libuv.Loop.get());
            } else {
                const empty_loop: void = undefined;
                _ = bun.Async.Closer.close(self.fd, empty_loop);
            }
        }
        _ = bun.destroy(self);
}

pub fn deinit(self: *FileResponseStream) void {
        _ = self.releaseInternal();
}

pub fn eventLoop(self: *FileResponseStream) jsc.EventLoopHandle {
        return jsc.EventLoopHandle.init(self.vm.eventLoop());
}

pub fn loop(self: *FileResponseStream) *Async.Loop {
        if (comptime bun.Environment.isWindows) {
            return self.eventLoop().loop().uv_loop;
        }
        return self.eventLoop().loop();
}
const State = packed struct(u8) {
    response_done: bool = false,
    finished: bool = false,
    errored: bool = false,
    resp_detached: bool = false,
    _: u4 = 0,
};
const Mode = enum { reader, sendfile };
const Sendfile = struct {
    socket_fd: bun.FD = bun.invalid_fd,
    remain: u64 = 0,
    offset: u64 = 0,
    has_set_on_writable: bool = false,
};
pub const StartOptions = struct {
    fd: bun.FD,
    auto_close: bool = true,
    resp: AnyResponse,
    vm: *jsc.VirtualMachine,
    file_type: bun.io.FileType,
    pollable: bool,
    offset: u64 = 0,
    length: ?u64 = null,
    idle_timeout: u8,
    ctx: *anyopaque,
    on_complete: *const fn (*anyopaque, AnyResponse) void,
    on_abort: ?*const fn (*anyopaque, AnyResponse) void = null,
    on_error: *const fn (*anyopaque, AnyResponse, bun.sys.Error) void,
};
const RefCount = bun.ptr.RefCount(@This(), "ref_count", deinit, .{});
pub const ref = RefCount.ref;
pub const deref = RefCount.deref;
const AbortFn = *const fn (*anyopaque, AnyResponse) void;
const Async = bun.Async;
const jsc = bun.jsc;
const uws = bun.uws;
const AnyResponse = uws.AnyResponse;
const log = bun.Output.scoped(.FileResponseStream, .hidden);
